const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-122.555169, 40.190004]);
  const date = '2020-08-25';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - Try CAMS black carbon products
  // CAMS provides black carbon aerosol optical depth
  let collection = ee.ImageCollection('ECMWF/CAMS/NRT')
    .filterDate(startDate, endDate)
    .filterBounds(point)
    .select('black_carbon_aerosol_optical_depth_550nm');

  let size = collection.size().getInfo();
  console.log(`Initial collection size: ${size}`);

  if (size === 0) {
    // Try different date range (±1 day)
    const altStart = startDate.advance(-1, 'day');
    const altEnd = endDate.advance(1, 'day');
    collection = ee.ImageCollection('ECMWF/CAMS/NRT')
      .filterDate(altStart, altEnd)
      .filterBounds(point)
      .select('black_carbon_aerosol_optical_depth_550nm');

    size = collection.size().getInfo();
    console.log(`Extended collection size: ${size}`);

    if (size === 0) {
      console.log('No data found for the specified location and date.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Get the image closest to the target date
  const image = collection.sort('system:time_start').first();

  // 4. Check pixel count
  const countResult = image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = countResult['black_carbon_aerosol_optical_depth_550nm'] || 0;
  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels at location.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Get black carbon value (optical depth)
  const result = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const bcValue = result['black_carbon_aerosol_optical_depth_550nm'];

  console.log(`Black carbon optical depth: ${bcValue}`);

  // 6. Validation & Final Answer
  // Note: The CAMS product provides optical depth, not concentration in mg/m²
  // Optical depth is unitless and typically ranges 0-1
  // The question asks about mg/m², which suggests mass concentration
  // This is likely a mismatch - optical depth cannot be directly compared to 12 mg/m²

  if (bcValue === null || bcValue === undefined || isNaN(bcValue)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Since we have optical depth (unitless, ~0-1 range) and question asks about mg/m²
  // This is comparing incompatible units - the data type doesn't match the question
  console.log('Data unit mismatch: optical depth vs mg/m² concentration.');
  console.log('<answer>D</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
